from pathlib import Path
import shutil, html, os
out=Path(os.environ.get('GAMEJAM_RELEASE_ROOT','/workspace/gamejam-release')); (out/'images').mkdir(exist_ok=True)
worktrees=Path(os.environ.get('GAMEJAM_WORKTREES','/workspace/gamejam'))
cards=[
('memorable','Small Hours','Memorable Moments','Two people · one screen','A secret choice becomes a shared action, then a keepsake both people authored.',str(worktrees/'memorable/memorable-moments-game/docs/evidence/01-desktop-home.png')),
('vivid','The Keeper’s Frame','Vivid 2.5D Photo','Solo · authored portrait mystery','Save a ferry. Choose what the portrait remembers. Return to see her permission change.',str(worktrees/'vivid/vivid-2.5d-photo-game/play/evidence/desktop-intro.png')),
('bell','The Thirteenth Bell','GameJam Contrast','Solo · time-loop mystery','Learn the town. Spend earned Momentum for one extra action, while every risk still counts.',str(worktrees/'bell/docs/evidence/07-after-new-scene-borrow.png'))]
parts=[]
for key,title,series,meta,desc,img in cards:
 shutil.copy2(img,out/'images'/f'{key}.png')
 parts.append(f'<article><a class="cover" href="{key}/index.html"><img src="images/{key}.png" alt="Tested {html.escape(title)} build" loading="lazy"></a><div class="cardbody"><span class="eyebrow">{series}</span><h2>{title}</h2><p class="meta">{meta}</p><p>{desc}</p><a class="play" href="{key}/index.html">Play this experiment <span aria-hidden="true">↗</span></a></div></article>')
journeys=[('Small Hours','Agent rehearsal; the off-screen social activity requires real people.',['Choose scene','A chooses privately','Pass screen','B chooses','Reveal together','Act together','Two details','Export keepsake']),('The Keeper’s Frame','Agent completed signal, privacy choice and actual reload.',['Meet Iona','Lean for evidence','Test signal','Recover from error','Save ferry','Choose promise','Return','Remembered permission']),('The Thirteenth Bell','Agent completed Original; revised extra-visit behavior independently checked.',['Forecast','Explore','Witness consequence','Cross midnight','Remember outcome','Spend Momentum','New choice','Extra visit'])]
flows=''.join('<div class="journey"><h3>'+name+'</h3><p class="meta">'+note+'</p><ol>'+''.join('<li>'+x+'</li>' for x in steps)+'</ol></div>' for name,note,steps in journeys)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GameJam · Playable fieldbook</title><style>
:root{--paper:#f3efe5;--ink:#203e37;--muted:#62716a;--line:#d0d5c7;--accent:#bd633f}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}a{color:inherit}main{max-width:1280px;margin:auto;padding:36px 30px 70px}header{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:18px;font-size:12px;letter-spacing:.14em;text-transform:uppercase}.intro{max-width:850px;margin:70px 0 45px}.eyebrow{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--accent)}h1{font:clamp(42px,6vw,76px)/1.07 Georgia,serif;letter-spacing:-.035em;margin:18px 0 24px}h1 em{color:var(--accent);font-weight:400}h2{font:30px/1.15 Georgia,serif;margin:12px 0}h3{font:25px Georgia,serif;margin-bottom:8px}.intro p{font-size:19px;max-width:740px}.meta{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}article{border:1px solid var(--line);background:#faf7f0;display:flex;flex-direction:column}.cover{display:block;height:210px;overflow:hidden;border-bottom:1px solid var(--line)}.cover img{width:100%;height:100%;object-fit:cover;object-position:top}.cardbody{padding:25px;flex:1;display:flex;flex-direction:column}.cardbody p{font-size:14px}.cardbody .meta{margin:0}.play{margin-top:auto;text-decoration:none;border-top:1px solid var(--line);padding-top:18px;display:flex;justify-content:space-between;font-weight:600}.note{margin:30px 0;padding:18px 24px;border-left:3px solid var(--accent);background:#e9e8da;font-size:14px}section{margin-top:60px}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:670px}th,td{text-align:left;vertical-align:top;padding:16px 18px;border-bottom:1px solid var(--line);font-size:14px}th{font-size:11px;text-transform:uppercase;letter-spacing:.12em}.journey{margin:30px 0}.journey ol{display:flex;list-style:none;padding:0;gap:9px;flex-wrap:wrap;counter-reset:step}.journey li{background:#fffaf0;border:1px solid var(--line);padding:12px 14px;font-size:12px;position:relative;counter-increment:step}.journey li:before{content:counter(step) ' · ';color:var(--accent)}.evidence{display:grid;grid-template-columns:1fr 1fr;gap:25px}.evidence>div{border-top:2px solid var(--ink);padding-top:12px}.links{display:flex;flex-wrap:wrap;gap:20px;margin-top:24px}.links a{font-size:14px}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.steps div{padding:18px;border:1px solid var(--line)}.steps b{display:block;font:22px Georgia,serif}.steps p{font-size:13px}code{background:#e6e8db;padding:2px 5px}footer{margin-top:60px;border-top:1px solid var(--line);padding-top:22px;font-size:12px;color:var(--muted)}@media(max-width:800px){.grid{grid-template-columns:1fr}.cover{height:280px}.evidence,.steps{grid-template-columns:1fr}main{padding:24px 18px}.intro{margin-top:42px}header{gap:20px}h1{font-size:45px}}
</style><main><header><span>GameJam · Playable fieldbook</span><span>5 October 2026 · Browser first</span></header><div class="intro"><span class="eyebrow">Three games. One testable direction.</span><h1>Let players choose<br><em>what survives.</em></h1><p>A moment made together. A portrait that remembers a decision. A town whose patterns give you another chance to act.</p><p class="meta">These are playable experiments built from the existing branches. Their behavior is tested. Their appeal to human players remains a hypothesis.</p></div><div class="grid">'''+''.join(parts)+'''</div><div class="note"><b>Start here:</b> Small Hours works best with two willing people together. In Bell, choose <b>Try GameJam / Contrast</b> on the opening card. Vivid uses an original illustration and authored choices; it does not provide free-text AI conversation.</div><section><span class="eyebrow">Why play · differentiation · signature</span><h2>Make a specific promise, then test it.</h2><div class="tablewrap"><table><thead><tr><th>Game</th><th>Desire to test</th><th>Competitive position</th><th>Signature experience</th></tr></thead><tbody><tr><td>Memorable Moments</td><td>See another person's perspective; create something together.</td><td>Paired already advertises reveal, missions and a timeline. Test the one-device, complete-session situation.</td><td>Two private viewpoints become one small act and a coauthored keepsake.</td></tr><tr><td>Vivid</td><td>Be recognized through an earned callback; understand a character.</td><td>Conversation already serves goals in Event[0] and Suck Up! Visual depth alone is insufficient.</td><td>A remembered decision changes what the portrait lets you see.</td></tr><tr><td>Bell</td><td>Become capable through understanding, rather than repetition.</td><td>Knowledge-led exploration is established. Make the benefit concrete in this short loop.</td><td>A correct forecast earns time for another choice, without removing risk.</td></tr></tbody></table></div></section><section><span class="eyebrow">Observed paths, not invented emotion scores</span><h2>Player journeys we walked.</h2>'''+flows+'''</section><section><span class="eyebrow">Launched games + criticism</span><h2>Outside our own prototypes.</h2><div class="evidence"><div><h3>We Become What We Behold</h3><p>Live play verified: hat photo → headline → hat adoption; affectionate couple → imposed mocking caption → couple leaves. An outburst photo produced a fear response. Ending not completed.</p><p class="meta">Later moving-target selection used read-only scene coordinates. This proves the sampled consequences, not unaided usability or human demand.</p><a href="https://ncase.itch.io/wbwwb">Creator's released game</a> · <a href="evidence/released-social/report.json">Play record</a></div><div><h3>Detective: Again!</h3><p>Live play reached the first accepted case. The client supplied a destination, then the dialogue closed without a persistent location note observed. The clock paused during conversation. Full case and time loop not completed.</p><p class="meta">Test environment needed the unchanged hosted game opened outside its iframe. Consumer load time is not inferred.</p><a href="https://kicodes.itch.io/detective-again">Creator's released game</a> · <a href="evidence/released-mystery/report.json">Play record</a></div></div><p>Criticism from Nintendo Life, Destructoid, PC Gamer, Andrew Plotkin, JayIsGames and Flash Forward Reviews is separated from our own observations in the fieldbook. Reviews inform a test; they do not establish a market.</p></section><section><span class="eyebrow">The next human evidence</span><h2>Use the rest of the jam to choose.</h2><div class="steps"><div><b>Watch a fresh start</b><p>Give only normal instructions. Record confusion and the first meaningful choice.</p></div><div><b>Ask for a prediction</b><p>What do they expect their action to change? Compare that with what they notice.</p></div><div><b>Offer another round</b><p>Record a voluntary choice. Do not confuse a completed tutorial with desire.</p></div><div><b>Keep one lead</b><p>Prioritize the consequence people explain and choose to revisit. Fix its largest observed obstacle.</p></div></div><p class="meta">itch.io is the proposed first platform for delivery fit, not a claim of audience demand or acceptance. Real mobile Safari/Chrome and recruited participants remain next steps.</p></section><section><span class="eyebrow">Source, evidence and recovery</span><h2>Everything stays reviewable.</h2><div class="links"><a href="field-report.md">Full fieldbook and journey diagrams</a><a href="human-playtest.csv" download>Blank human playtest sheet</a><a href="manifest.json">Build commits and hashes</a><a href="package-validation.json">Portable build validation</a><a href="https://github.com/PaperStrange/IndiaGames/branches">Separate remote game branches</a></div><p class="meta">All three builds are self-contained HTML. For consistent save behavior, unzip this package and run <code>python3 -m http.server 8080</code> here, then open the address shown by the server. No account or model API is required.</p></section><footer>Six independent agent sessions covered implementation, research and released-game play. No human participant results are invented. Source checkpoints are synced one game per branch; pre-jam and final Git bundles protect recovery.</footer></main></html>'''
(out/'index.html').write_text(page)
print(out/'index.html')
